/* eslint-disable @typescript-eslint/naming-convention */
import { DatePipe } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { FormBuilder } from '@angular/forms';
import { Router, ActivatedRoute } from '@angular/router';
import { LoadingController, ToastController, AlertController, IonRouterOutlet } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { IReportFilterViewModel, ReportFilterViewModel, IReportViewModel } from 'src/app/data/model/common/BaseModel';
import { CourseService } from 'src/app/data/service/course/course.service';

@Component({
  selector: 'app-report-course-question',
  templateUrl: './report-course-question.component.html',
  styleUrls: ['./report-course-question.component.scss'],
})
export class ReportCourseQuestionPage implements OnInit {

  isSelected = false;
  unSeenReports = [];
  isUnSeenReportsLoading = true;
  selectedId = 0;
  search = '';
  notfound = false;
  filteredReports: IReportFilterViewModel = new ReportFilterViewModel(1, 12, '');
  selectedReport: IReportViewModel;
  reportsCount = -1;

  constructor(
    private router: Router,
    private activatedRoute: ActivatedRoute,
    private courseService: CourseService,
    public loadingController: LoadingController,
    public toastController: ToastController,
    public alertController: AlertController,
    private fb: FormBuilder,
    public datepipe: DatePipe,
    public routerOutlet: IonRouterOutlet
  ) { }

  ionViewWillEnter() {

    this.isSelected = false;

    let filter: IReportFilterViewModel;

    this.activatedRoute.params.subscribe(params => {

      const id = params.id;

      if (id === undefined || id == null || +id <= 0) {

        this.isUnSeenReportsLoading = true;
        this.unSeenReports = [];
        SharedIonic.loading(this.loadingController);

        this.isSelected = false;
        this.selectedId = 0;
        filter = new ReportFilterViewModel(1, 12, this.search);

        this.courseService.GetAdminCourseQuestionReportsByFilter(filter).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.filteredReports = res.data;
              this.notfound = false;

            } else if (res.status === GResponse.NotFoundStatus) {

              this.notfound = true;
              SharedIonic.toast(this.toastController, 'موردی یافت نشد');
            }
          },
          err => {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
          }
        );

        this.courseService.GetAdminUnSeenCourseQuestionReportsList().subscribe(
          res => {
            if (res.status === GResponse.SuccessStatus) {
              this.unSeenReports = res.data;
              this.isUnSeenReportsLoading = false;

            } else if (res.status === GResponse.NotFoundStatus) {

              this.isUnSeenReportsLoading = false;
              SharedIonic.toast(this.toastController, 'گزارش جدید ندارید');
            }
          },
          err => {
            SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
          }
        );

        this.courseService.GetAdminCourseQuestionReportsListCount().subscribe(
          res => {
            if (res.status === GResponse.SuccessStatus) {
              this.reportsCount = res.data;

            } else if (res.status === GResponse.NotFoundStatus) {
              this.reportsCount = -1;
            }
          },
          err => {
            this.reportsCount = -1;
            SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
          }
        );
      } else {

        SharedIonic.loading(this.loadingController);

        this.isSelected = true;
        this.selectedId = +id;

        this.courseService.GetAdminCourseQuestionReportDetailsById(this.selectedId).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.selectedReport = res.data;

            } else if (res.status === GResponse.NotFoundStatus) {

              SharedIonic.toast(this.toastController, 'پاسخی ثبت نشده است');
            }
          },
          err => {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
          }
        );

      }
    });
  }

  ngOnInit() {
  }

  getTime(date: Date): string {

    return this.datepipe.transform(date, 'HH:mm:ss');
  }

  doRefresh(event) {

    setTimeout(() => {

      location.reload();
      event.target.complete();
    }, 2000);
  }

  setQueryParams2(pageId: number) {

    SharedIonic.loading(this.loadingController);

    const page = pageId < 1 ? 1 : pageId;

    const filter = new ReportFilterViewModel
      (page, this.filteredReports.takeEntity, this.search, this.filteredReports.sortId);

    this.filteredReports = filter;

    this.courseService.GetAdminCourseQuestionReportsByFilter(filter).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.filteredReports = res.data;
          this.notfound = false;

        } else if (res.status === GResponse.NotFoundStatus) {

          this.notfound = true;
          SharedIonic.toast(this.toastController, 'موردی یافت نشد');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
      }
    );
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }
  goPreviousPage2() {

    if (this.filteredReports.startPage == null) {
      return;
    }
    if (this.filteredReports.pageId > this.filteredReports.startPage && +this.filteredReports.pageId - 1 > 0) {
      this.setQueryParams2(+this.filteredReports.pageId - 1);
    }
  }

  goNextPage2() {

    if (this.filteredReports.endPage == null) {
      return;
    }
    if (this.filteredReports.pageId < this.filteredReports.endPage) {
      this.setQueryParams2(+this.filteredReports.pageId + 1);
    }
  }

  goPage2(pageId: number | string) {
    this.setQueryParams2(+pageId);
  }

  onSelectItem(id: number) {

    // this.selectedId = +model.id;
    // this.report = model;
  }

  onVerify() {

    SharedIonic.loading(this.loadingController);

    this.courseService.AdminVerifyCourseQuestionReport(this.selectedReport.id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          this.selectedReport.isVerify = true;

        } else {

          SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
      }
    );
  }

  async presentVerifyAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به تایید کردن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'تایید کردن',
          handler: () => {
            this.onVerify();
          }
        }
      ]
    });

    await alert.present();
  }

  onDeVerify() {

    SharedIonic.loading(this.loadingController);

    this.courseService.AdminDeVerifyCourseQuestionReport(this.selectedReport.id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          this.selectedReport.isVerify = false;

        } else {

          SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
      }
    );
  }

  async presentDeVerifyAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا عدم تایید هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'عدم تایید',
          handler: () => {
            this.onDeVerify();
          }
        }
      ]
    });

    await alert.present();
  }

}
